// Edit this list: one entry per RSS feed (mirrors config.yaml in the Python version)
return [
  { json: { source: 'Hacker News Front Page', url: 'https://hnrss.org/frontpage' } },
  { json: { source: 'Python Insider', url: 'https://blog.python.org/feeds/posts/default?alt=rss' } },
  { json: { source: 'GitHub Blog', url: 'https://github.blog/feed/' } },
];

// Tag every feed entry with the feed it came from and keep at most 15 per source
const MAX_PER_SOURCE = 15;
const counts = {};
const out = [];
$input.all().forEach((item, i) => {
  let source;
  try { source = $('Feed List').itemMatching(i).json.source; }
  catch (e) { source = (item.json.link || '').split('/')[2] || 'RSS'; }
  counts[source] = (counts[source] || 0) + 1;
  if (counts[source] > MAX_PER_SOURCE) return;
  const link = item.json.link || '';
  out.push({ json: {
    source,
    title: String(item.json.title || '(no title)').replace(/\s+/g, ' ').trim(),
    link,
    published: item.json.isoDate || item.json.pubDate || '',
    uid: item.json.guid || link || item.json.title,
  }});
});
return out;

// Turn the extracted text blocks into items; the uid is the text itself, so any change shows up as new
const PAGE_URL = 'https://quotes.toscrape.com/';
const texts = $input.first().json.quotes || [];
return texts
  .map(t => String(t).replace(/\s+/g, ' ').trim())
  .filter(Boolean)
  .map(t => ({ json: { source: 'Quotes page (change monitor demo)', title: t.slice(0, 200), link: PAGE_URL, published: '', uid: PAGE_URL + '|' + t } }));

// Keep only items not reported before (remembered in workflow static data),
// optionally filter by keywords, and build one Markdown digest.
// Note: static data persists only for production runs (active workflow), not manual test runs.
const KEYWORDS = [];               // e.g. ['python', 'ai'] - empty = keep everything
const TITLE = 'Daily Tech Digest';

const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

const all = $input.all().map(i => i.json).filter(i => i.uid);  // drop empty/error items
const fresh = all.filter(it =>
  !store.seen[it.uid] &&
  (KEYWORDS.length === 0 || KEYWORDS.some(k => it.title.toLowerCase().includes(k.toLowerCase())))
);
for (const it of all) store.seen[it.uid] = Date.now();
// forget entries older than 60 days so static data stays small
const cutoff = Date.now() - 60 * 24 * 3600 * 1000;
for (const [k, t] of Object.entries(store.seen)) if (t < cutoff) delete store.seen[k];

const today = new Date().toISOString().slice(0, 10);
const sources = [...new Set(all.map(i => i.source))];
let md = `# ${TITLE} - ${today}\n\n**${fresh.length} new item(s)** from ${sources.length} source(s).\n`;
for (const s of sources) {
  const group = fresh.filter(i => i.source === s);
  const checked = all.filter(i => i.source === s).length;
  md += `\n## ${s} (${group.length} new / ${checked} checked)\n\n`;
  md += group.length ? group.map(i => `- [${i.title}](${i.link})`).join('\n') + '\n' : '_No new items._\n';
}
return [{ json: { title: TITLE, date: today, count: fresh.length, items: fresh, markdown: md } }];
